import sys
import time
from collections import defaultdict

def parse_accounts(accounts_path):
    accounts = defaultdict(int)
    with open(accounts_path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            token, budget_str = line.split(maxsplit=1)
            accounts[token] = int(budget_str)
    return accounts

def process_jobs(accounts, jobs, rate):
    allow_count = 0
    start_time = time.time()
    results = []

    for line_num, job in enumerate(jobs, 1):
        token, cost, expr = job
        condition = eval(expr, {'cost': cost, 'line': line_num})

        if token not in accounts:
            results.append(f"deny {token} unknown_token")
        elif not condition:
            results.append(f"deny {token} condition_false")
        else:
            if accounts[token] < cost:
                results.append(f"deny {token} budget_exhausted")
            else:
                accounts[token] -= cost
                results.append(f"allow {token} {accounts[token]}")
                allow_count += 1

                # Pacing logic
                current_time = time.time()
                if current_time - start_time >= 1:
                    if allow_count >= rate:
                        time.sleep(1 - (current_time - start_time))
                        allow_count = 0
                        start_time = time.time()
                    else:
                        start_time = current_time

    return results

def main():
    if len(sys.argv) != 3 or sys.argv[1] != '--rate':
        print("Usage: python gateway.py --rate <dispatches_per_second> <accounts_path>", file=sys.stderr)
        sys.exit(1)

    try:
        rate = int(sys.argv[2])
        if rate <= 0:
            print("Rate must be a positive integer", file=sys.stderr)
            sys.exit(1)
    except ValueError:
        print("Rate must be an integer", file=sys.stderr)
        sys.exit(1)

    accounts_path = sys.argv[3]
    accounts = parse_accounts(accounts_path)

    jobs = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split(maxsplit=2)
        if len(parts) != 3:
            continue
        token, cost_str, expr = parts
        try:
            cost = int(cost_str)
        except ValueError:
            continue
        jobs.append((token, cost, expr))

    results = process_jobs(accounts, jobs, rate)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()

import sys
import time
from collections import defaultdict

def main():
    if len(sys.argv) != 3:
        print("Usage: python gateway.py RATE TOKENS_PATH", file=sys.stderr)
        sys.exit(1)

    rate = int(sys.argv[1])
    tokens_path = sys.argv[2]

    with open(tokens_path, 'r') as f:
        token_budgets = {}
        for line in f:
            line = line.strip()
            if not line:
                continue
            token, budget_str = line.split(maxsplit=1)
            token_budgets[token] = int(budget_str)

    last_allow_time = 0
    allow_count = 0

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        token, expr = line.split(maxsplit=1)

        if token not in token_budgets:
            print(f"deny {token}")
            continue

        try:
            cost = eval(expr)
        except:
            print(f"deny {token}")
            continue

        if cost < 0:
            print(f"deny {token}")
            continue

        if token_budgets[token] < cost:
            print(f"deny {token}")
            continue

        current_time = time.time()
        if current_time - last_allow_time < 1:
            if allow_count >= rate:
                time.sleep(1 - (current_time - last_allow_time))
                current_time = time.time()
                if current_time - last_allow_time < 1:
                    continue
            allow_count = 0

        token_budgets[token] -= cost
        print(f"allow {token} {token_budgets[token]}")
        last_allow_time = current_time
        allow_count += 1

if __name__ == "__main__":
    main()
